# package.json
"simple-git-hooks": {
  "pre-commit": "npx lint-staged",
  "commit-msg": "npx --no -- commitlint --edit $1"
},
"scripts": { "prepare": "simple-git-hooks" }

# .githooks/pre-push
#!/bin/sh
[ -f tsconfig.json ] || exit 0
command -v npx >/dev/null 2>&1 || { echo 'npx absent; skipping typecheck' >&2; exit 0; }
npx --no -- tsc --noEmit || { echo 'pre-push: type errors' >&2; exit 1; }

#!/bin/sh
command -v npx >/dev/null 2>&1 || exit 0
[ -f knip.json ] || [ -f knip.jsonc ] || exit 0
npx --no -- knip --production; rc=$?
[ "$rc" -eq 2 ] && { echo 'knip misconfigured' >&2; exit 1; }
[ "$rc" -eq 1 ] && { echo 'dead exports/deps found' >&2; exit 1; }
exit 0

# .size-limit.json
[ { "path": "dist/app-*.js", "limit": "35 kB" } ]
# pre-push
#!/bin/sh
[ -f .size-limit.json ] || exit 0
npx --no -- size-limit || { echo 'bundle budget exceeded' >&2; exit 1; }

# pre-commit: lint staged JSX for a11y. Degrades to a no-op if eslint is absent.
files=$(git diff --cached --name-only --diff-filter=ACM | grep -E '\.(jsx|tsx)$')
[ -z "$files" ] && exit 0
command -v npx >/dev/null 2>&1 || { echo "note: npx absent, skipping a11y lint"; exit 0; }
npx --no-install eslint --version >/dev/null 2>&1 || { echo "note: eslint not installed, skipping"; exit 0; }
echo "$files" | tr '\n' '\0' | xargs -0 npx --no-install eslint --max-warnings 0 || {
  echo "BLOCKED: jsx-a11y violations in staged files"; exit 1; }
exit 0

# pre-commit: stylelint staged CSS. No-op when stylelint is not installed.
css=$(git diff --cached --name-only --diff-filter=ACM | grep -Ei '\.(css|scss|sass|less)$')
[ -z "$css" ] && exit 0
command -v npx >/dev/null 2>&1 || exit 0
npx --no-install stylelint --version >/dev/null 2>&1 || { echo "note: stylelint absent, skipping"; exit 0; }
echo "$css" | tr '\n' '\0' | xargs -0 npx --no-install stylelint --max-warnings 0 || {
  echo "BLOCKED: stylelint (design-system drift) in staged CSS"; exit 1; }
exit 0

