if command -v gitleaks >/dev/null 2>&1; then
  gitleaks git --pre-commit --redact --staged --verbose || {
    echo 'BLOCK[gitleaks]: staged secret. Rotate it, do not just unstage.' >&2; exit 1; }
fi

if command -v trufflehog >/dev/null 2>&1; then
  trufflehog git "file://$(git rev-parse --show-toplevel)" \
    --since-commit HEAD --results=verified --fail --no-update >&2 || {
    echo 'BLOCK[trufflehog]: VERIFIED-LIVE credential. Rotate at the provider now.' >&2; exit 1; }
fi

# VERIFIED against positive+negative controls. Stripping the diff '+' marker via
# substr($0,2) is MANDATORY: a bare '+' self-matches the concat pattern and fires
# on every added line.
added() {
  git diff --cached -U0 --diff-filter=ACM -- "$@" | awk '
    /^\+\+\+ b\// { f=substr($0,7); next }
    /^@@/ { split($0,a,"+"); split(a[2],b,/[, ]/); n=b[1]; next }
    /^\+/ { print f ":" n++ ":" substr($0,2) }'
}
SQLKW='SELECT|INSERT INTO|UPDATE |DELETE FROM'
INTERP='("[[:space:]]*\+)|(\+[[:space:]]*")|(\{[A-Za-z_$])|(\$\{)|(#\{)|(\.format\()|(%[[:space:]]*\([A-Za-z_])'
hits=$(added '*.py' '*.go' '*.js' '*.ts' '*.rb' '*.java' '*.php' '*.cs' \
  | grep -iE "($SQLKW)" | grep -E "$INTERP" || true)
[ -n "$hits" ] && { echo 'BLOCK[raw-sql-interpolation]: use bound parameters.' >&2
  printf '%s\n' "$hits" >&2; exit 1; }

#!/bin/sh
# pre-commit: description must be trigger-shaped, body must fit budget
fail=0
for f in .harnemons/*/skills/*/SKILL.md; do
  [ -f "$f" ] || continue
  sed -n '1,15p' "$f" | grep -qi '^description: .*[Uu]se when' || { echo "description not trigger-shaped: $f" >&2; fail=1; }
  grep -q '^@\|(@skills/' "$f" && { echo "forbidden @-import (force-loads context): $f" >&2; fail=1; }
  w=$(wc -w < "$f")
  [ "$w" -gt 5000 ] && { echo "skill body $w words, split it: $f" >&2; fail=1; }
done
exit $fail

#!/bin/sh
# pre-commit: frontmatter name must equal directory name; body under 500 lines
fail=0
for f in .harnemons/*/skills/*/SKILL.md; do
  [ -f "$f" ] || continue
  dir=$(basename "$(dirname "$f")")
  head -1 "$f" | grep -q '^---$' || { echo "no frontmatter: $f" >&2; fail=1; continue; }
  nm=$(sed -n '2,15p' "$f" | sed -n 's/^name: *//p' | head -1)
  [ "$nm" = "$dir" ] || { echo "name '$nm' != dir '$dir': $f" >&2; fail=1; }
  echo "$dir" | grep -Eq '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$' || { echo "bad dir name: $dir" >&2; fail=1; }
  n=$(wc -l < "$f"); [ "$n" -gt 500 ] && { echo "SKILL.md $n lines >500: $f" >&2; fail=1; }
done
exit $fail
